mapper.select:
SELECT t.*,ta.templename FROM TBL_ASSESS t inner join TBL_ASSESSTEMPLE
ta on t.asstemid=ta.asstemid WHERE 1=1

	AND t.TBLCOMANY=#{queryParam.tblcomany}



	AND ASSESSID LIKE
	concat(concat('%',#{queryParam.assessid}),'%')


	AND ASSESSNAME LIKE
	concat(concat('%',#{queryParam.assessname}),'%')



	and startdate >=#{queryParam.startdate}


	and startdate <=#{queryParam.startdates}


	and endDate >=#{queryParam.enddate}


	and endDate <=#{queryParam.enddates}


	${sql}

order by t.assid desc

select distinct t.*,ta.templename from TBL_ASSESS t inner join TBL_ASSESSTEMPLE ta on t.asstemid=ta.asstemid inner join TBL_ASSESS_MARK TAM on t.ASSID = TAM.ASSID left join TBL_ASSESS_STAFF TAS on TAM.ASSMARKID = TAS.ASSMARKID where 1=1
and t.ASSSTATUS = #{queryParam.assstatus} and TAS.STATUS!=2
and ( TAS.STAFFID = #{queryParam.staffid} or t.LEADERID = #{queryParam.staffid})
AND ASSESSID LIKE concat(concat('%',#{queryParam.assessid}),'%')
AND ASSESSNAME LIKE concat(concat('%',#{queryParam.assessname}),'%')
and startdate >=#{queryParam.startdate}
and enddate <=#{queryParam.enddate}
${sql}

SELECT t.*,ta.templename FROM TBL_ASSESS t inner join TBL_ASSESSTEMPLE
ta on t.asstemid=ta.asstemid WHERE 1=1


	AND t.TBLCOMANY=#{queryParam.tblcomany}



	AND ASSESSID LIKE
	concat(concat('%',#{queryParam.assessid}),'%')


	AND ASSESSNAME LIKE
	concat(concat('%',#{queryParam.assessname}),'%')



	and startdate >=#{queryParam.startdate}


	and startdate <=#{queryParam.startdates}


	and endDate >=#{queryParam.enddate}


	and endDate <=#{queryParam.enddates}



	${sql}

order by t.assid desc

select distinct t.*,ta.templename,TAT.FINALSCORE as
FINALSCORENEW,TAT.CHECKLEVEL,TAT.CHECKREASON,TAT.FINALLEVEL from
TBL_ASSESS t
inner join TBL_ASSESSTEMPLE ta on t.asstemid=ta.asstemid
left join TBL_ASSESS_MARK TAM on t.ASSID = TAM.ASSID
left join
TBL_ASSESS_TARGET TAT on TAT.assid = t.ASSID where t.assstatus
in (3,4)

	AND t.TBLCOMANY=#{queryParam.tblcomany}




	AND ASSESSID LIKE
	concat(concat('%',#{queryParam.assessid}),'%')


	AND ASSESSNAME LIKE
	concat(concat('%',#{queryParam.assessname}),'%')


	and startdate >=#{queryParam.startdate}


	and startdate <=#{queryParam.startdates}


	and endDate >=#{queryParam.enddate}


	and endDate <=#{queryParam.enddates}



	and LINKORGID = #{queryParam.orgid}




	${sql}


order by t.assid desc

SELECT COUNT(*) from Tbl_ASSESS t where 1=1

	and t.assessid=#{queryParam.assessid}


	and TBLCOMANY IN

		#{item}

SELECT   max(REPLACE(${queryParam.column },REPLACE('${queryParam.jgf}','%',''),'')) FROM ${queryParam.tblName} WHERE 1=1

	and ${queryParam.orgCol } IN

		#{item}




		AND ${queryParam.column } LIKE #{queryParam.jgf}
		AND (REPLACE(REPLACE(${queryParam.column },REPLACE('${queryParam.jgf}','${queryParam.sep }%',''),''),REPLACE(REPLACE(${queryParam.column },REPLACE('${queryParam.jgf}','${queryParam.sep }%',''),''),'${queryParam.sep }','')) = '${queryParam.sep }' )




	and ${queryParam.chChoiceCol} #{queryParam.bjf}
	${queryParam.chChoiceCol}

select distinct t.*,ta.templename,CAST(TAT.FINALSCORE AS decimal(10, 2)) as FINALSCORENEW,TAT.CHECKLEVEL,TAT.CHECKREASON,TAT.FINALLEVEL from TBL_ASSESS t inner join TBL_ASSESSTEMPLE ta on t.asstemid=ta.asstemid left join TBL_ASSESS_MARK TAM on t.ASSID = TAM.ASSID left join TBL_ASSESS_TARGET TAT on TAT.assid = t.ASSID where t.assstatus in (3,4)
AND t.TBLCOMANY=#{orgId}
and year(t.CREATETIME)=#{year}
AND ( CREATESTAFFID=#{staffid} OR LEADERID =#{staffid} )
order by t.assid desc
